46	  if (config.memory_limit_bytes < MIN_MEMORY_LIMIT_BYTES) {
47	    return Status::InvalidArgument("memory_limit_bytes must be greater than ",
48	                                   MIN_MEMORY_LIMIT_BYTES);
49	  }
50	
51	  if (config.memory_limit_bytes > CgroupUtil::get_memory_limit()) {
52	    return Status::InvalidArgument("memory_limit_bytes must be less than ",
53	                                   CgroupUtil::get_memory_limit());
54	  }
55	
56	  // Validate query thread count
57	  if (config.query_thread_count == 0) {
58	    return Status::InvalidArgument("query_thread_count must be greater than 0");
59	  }
60	
61	  // Validate invert_to_forward_scan_ratio (should be between 0 and 1)
62	  if (config.invert_to_forward_scan_ratio < 0.0f ||
63	      config.invert_to_forward_scan_ratio > 1.0f) {
64	    return Status::InvalidArgument(
65	        "invert_to_forward_scan_ratio must be between 0 and 1");
66	  }
67	
68	  // Validate brute_force_by_keys_ratio (should be between 0 and 1)
69	  if (config.brute_force_by_keys_ratio < 0.0f ||
70	      config.brute_force_by_keys_ratio > 1.0f) {
71	    return Status::InvalidArgument(
72	        "brute_force_by_keys_ratio must be between 0 and 1");
73	  }
74	
75	  // Validate fts_brute_force_by_keys_ratio (should be between 0 and 1)
76	  if (config.fts_brute_force_by_keys_ratio < 0.0f ||
77	      config.fts_brute_force_by_keys_ratio > 1.0f) {
78	    return Status::InvalidArgument(
79	        "fts_brute_force_by_keys_ratio must be between 0 and 1");
80	  }
81	
82	  // Validate optimize thread count
83	  if (config.optimize_thread_count == 0) {
84	    return Status::InvalidArgument(
85	        "optimize_thread_count must be greater than 0");
86	  }
87	
88	  // Validate log configuration
89	  if (config.log_config->get_logger_type() == FILE_LOG_TYPE_NAME) {
90	    auto log_config =
91	        std::dynamic_pointer_cast<FileLogConfig>(config.log_config);
92	
93	    // Validate file log specific configurations
94	    if (log_config->dir.empty()) {
95	      return Status::InvalidArgument(
96	          "log_dir cannot be empty when set to FileLogger");
97	    }
98	
99	    if (log_config->basename.empty()) {
100	      return Status::InvalidArgument(
101	          "log_file basename cannot be empty when set to FileLogger");
102	    }
103	
104	    if (log_config->file_size <= MIN_LOG_FILE_SIZE) {
105	      return Status::InvalidArgument("log file_size must be greater than ",
106	                                     MIN_LOG_FILE_SIZE,
107	                                     " when set to FileLogger");
108	    }
109	
110	    if (log_config->overdue_days == 0) {
111	      return Status::InvalidArgument(
112	          "log_overdue_days must be greater than 0 when set to FileLogger");
113	    }
114	  }
115	
116	  return Status::OK();
117	}
118	
119	Status GlobalConfig::initialize(const ConfigData &config) {
120	  // Use atomic compare-exchange to ensure only one initialization
121	  bool expected = false;
122	  if (!initialized_.compare_exchange_strong(expected, true)) {
123	    return Status::OK();
124	  }
125	
126	  auto s = validate(config);
127	  CHECK_RETURN_STATUS(s);
128	
129	  config_ = config;
130	
131	  s = LogUtil::Init(log_dir(), log_file_basename(), int(log_level()),
132	                    log_type(), log_file_size(), log_overdue_days());
133	  CHECK_RETURN_STATUS(s);
134	
135	  if (std::atexit(ExitLogHandler) != 0) {
136	    std::cerr << "Failed to register exit handler" << std::endl;
137	    return Status::InternalError("Failed to register exit handler");
138	  }
139	
140	  GlobalResource::Instance().initialize();
141	  return Status::OK();
142	}
