153	                  file_path_.c_str(), core::IndexError::What(ret));
154	        return ret;
155	      }
156	      break;
157	    }
158	    case StorageOptions::StorageType::kBufferPool: {
159	      storage_params.set(core::BUFFER_READ_STORAGE_WARMUP_MODE,
160	                         core::BUFFER_READ_STORAGE_WARMUP_NONE);
