169	                  file_path_.c_str(), core::IndexError::What(ret));
170	        return ret;
171	      }
172	      break;
173	    }
174	    default: {
175	      LOG_ERROR("Unsupported storage type");
176	      return core::IndexError_Unsupported;
177	    }
178	  }
179	
180	  if (!storage_options.create_new) {
181	    int ret = storage_->open(file_path_, false);
182	    if (ret != 0) {
183	      LOG_ERROR("Failed to open storage, path: %s, err: %s", file_path_.c_str(),
184	                core::IndexError::What(ret));
185	      return core::IndexError_Runtime;
186	    }
187	    if (streamer_ == nullptr || streamer_->open(storage_) != 0) {
188	      LOG_ERROR("Failed to open streamer, path: %s", file_path_.c_str());
189	      return core::IndexError_Runtime;
190	    }
191	    is_trained_ = true;
192	  }
193	  is_open_ = true;
194	  return 0;
195	}
196	
197	int DiskAnnIndex::generate_holder() {
198	  return BuildMultiPassHolder(param_.data_type, param_.dimension, doc_cache_,
199	                              converter_, &holder_);
200	}
201	
202	int DiskAnnIndex::add(const VectorData &vector, uint32_t doc_id) {
203	  if (is_trained_ || build_stage_ != BuildStage::kCollecting) {
204	    LOG_ERROR("this diskann index is trained or has a pending build");
205	    return core::IndexError_Runtime;
206	  }
207	  if (!std::holds_alternative<DenseVector>(vector.vector)) {
208	    LOG_ERROR("Invalid vector data");
209	    return core::IndexError_Runtime;
210	  }
211	  const DenseVector &dense_vector = std::get<DenseVector>(vector.vector);
212	  std::string out_vector_buffer = std::string(
213	      static_cast<const char *>(dense_vector.data),
214	      input_vector_meta_.dimension() * input_vector_meta_.unit_size());
215	
216	  std::lock_guard<std::mutex> lock(mutex_);
217	  if (doc_cache_.size() <= doc_id) {
218	    doc_cache_.resize(doc_id + 1, std::make_pair(kInvalidKey, std::string{}));
219	  }
220	  doc_cache_[doc_id] = std::make_pair(doc_id, std::move(out_vector_buffer));
221	  return 0;
222	}
223	
224	int DiskAnnIndex::train() {
225	  if (is_trained_) return 0;
226	  if (build_stage_ == BuildStage::kCollecting) {
227	    int ret = reset_builder();
228	    if (ret != 0) return ret;
229	    ret = generate_holder();
230	    if (ret != 0) return ret;
231	    ret = builder_->train(holder_);
232	    if (ret != 0) return ret;
233	    build_stage_ = BuildStage::kTrained;
234	  }
235	  if (build_stage_ == BuildStage::kTrained) {
236	    int ret = builder_->build(holder_);
237	    if (ret != 0) {
238	      // A partial graph cannot be resumed. Recreate it on the next attempt
239	      // from the retained input cache.
240	      build_stage_ = BuildStage::kCollecting;
241	      return ret;
242	    }
243	    build_stage_ = BuildStage::kBuilt;
244	  }
245	  return dump_and_open();
246	}
247	
248	int DiskAnnIndex::reset_builder() {
249	  auto next = core::IndexFactory::CreateBuilder("DiskAnnBuilder");
250	  if (!next) return core::IndexError_NoExist;
251	  int ret = next->init(converter_ ? converter_->meta() : proxima_index_meta_,
252	                       proxima_index_params_);
253	  if (ret != 0) return ret;
254	  builder_ = std::move(next);
255	  return 0;
256	}
257	
258	int DiskAnnIndex::dump_and_open() {
259	  if (build_stage_ == BuildStage::kBuilt) {
260	    auto dumper = core::IndexFactory::CreateDumper("FileDumper");
261	    if (!dumper) return core::IndexError_NoExist;
262	    int ret = dumper->create(file_path_);
263	    if (ret != 0) return ret;
264	    AILEGO_DEFER([&]() {
265	      if (dumper) dumper->close();
266	    });
267	    ret = builder_->dump(dumper);
268	    if (ret != 0) return ret;
269	    if (converter_) {
270	      ret = converter_->dump(dumper);
271	      if (ret != 0) return ret;
272	    }
273	    ret = dumper->close();
274	    if (ret != 0) return ret;
275	    dumper.reset();
276	    ret = reset_builder();
277	    if (ret != 0) return ret;
278	    build_stage_ = BuildStage::kDumped;
279	  } else if (build_stage_ != BuildStage::kDumped) {
280	    return core::IndexError_NoReady;
281	  }
282	  AILEGO_DEFER([&]() {
283	    if (!is_trained_) {
284	      if (streamer_) streamer_->close();
285	      storage_->close();
286	    }
287	  });
288	  int ret = storage_->open(file_path_, false);
289	  if (ret != 0) return ret;
290	  if (!streamer_) return core::IndexError_NoReady;
291	  ret = streamer_->open(storage_);
292	  if (ret != 0) return ret;
293	  if (reformer_) {
294	    ret = reformer_->load(storage_);
295	    if (ret != 0) return ret;
296	  }
297	  is_trained_ = true;
298	  converter_.reset();
299	  holder_.reset();
300	  decltype(doc_cache_)().swap(doc_cache_);
301	  return 0;
302	}
303	
304	int DiskAnnIndex::_dense_fetch(const uint32_t doc_id,
305	                               VectorDataBuffer *vector_data_buffer) {
306	  if (is_trained_) {
307	    return Index::_dense_fetch(doc_id, vector_data_buffer);
308	  } else {
309	    std::lock_guard<std::mutex> lock(mutex_);
310	    if (doc_id >= doc_cache_.size()) return core::IndexError_OutOfRange;
311	    if (doc_cache_[doc_id].first == kInvalidKey)
312	      return core::IndexError_NoExist;
313	    DenseVectorBuffer dense_vector_buffer;
314	    std::string &out_vector_buffer = dense_vector_buffer.data;
315	    out_vector_buffer = doc_cache_[doc_id].second;
316	    vector_data_buffer->vector_buffer = std::move(dense_vector_buffer);
317	    return 0;
318	  }
319	}
320	
321	int DiskAnnIndex::_prepare_for_search(
322	    const VectorData & /*query*/,
323	    const BaseIndexQueryParam::Pointer &search_param,
324	    core::IndexContext::Pointer &context) {
325	  const auto &diskann_search_param =
326	      std::dynamic_pointer_cast<DiskAnnQueryParam>(search_param);
327	  if (diskann_search_param == nullptr) {
328	    LOG_ERROR("Invalid search param: expected DiskAnnQueryParam");
329	    return core::IndexError_Runtime;
330	  }
331	
332	  if (search_param->group_by_param && search_param->group_by_param->group_by) {
333	    LOG_ERROR("group_by search is not supported for DiskAnn index");
334	    return core::IndexError_Unsupported;
335	  }
336	
337	  context->set_topk(diskann_search_param->topk);
338	  context->set_fetch_vector(diskann_search_param->fetch_vector);
339	  if (diskann_search_param->filter) {
340	    context->set_filter(*diskann_search_param->filter);
341	  } else {
342	    context->reset_filter();
343	  }
344	  if (diskann_search_param->radius > 0.0f) {
345	    context->set_threshold(diskann_search_param->radius);
346	  } else {
347	    context->reset_threshold();
348	  }
349	
350	  // Propagate the query-time beam-search list size into the context. Must be
351	  // at least topk to keep enough candidates for a correct result.
352	  ailego::Params params;
353	  params.set(
354	      core::PARAM_DISKANN_SEARCHER_LIST_SIZE,
355	      std::max(diskann_search_param->topk, diskann_search_param->list_size));
356	  context->update(params);
357	
358	  return 0;
359	}
360	
361	int DiskAnnIndex::merge(const std::vector<Index::Pointer> &indexes,
362	                        const IndexFilter &filter,
363	                        const MergeOptions &options) {
364	  if (indexes.empty()) return 0;
365	  if (is_trained_) return core::IndexError_Unsupported;
366	  int ret = reset_builder();
367	  if (ret != 0) return ret;
368	  build_stage_ = BuildStage::kCollecting;
369	  ret = Index::merge(indexes, filter, options);
370	  if (ret != 0) return ret;
371	  build_stage_ = BuildStage::kBuilt;
372	  is_trained_ = false;
373	  return dump_and_open();
374	}
375	
376	#endif  // DISKANN_SUPPORTED
377	
378	}  // namespace zvec::core_interface
