175	// Simple Lloyd's KMeans for one chunk (templated on data type T).
176	// ---------------------------------------------------------------------------
177	
178	template <typename T>
179	void PqInt8Quantizer::train_chunk(const T *data, size_t num, size_t stride,
180	                                  size_t sub_idx, uint32_t max_iters) {
181	  const size_t k = kNumCentroids;
182	  const size_t d = chunk_dim(sub_idx);
183	  const size_t offset = chunk_offsets_[sub_idx];
184	  uint8_t *centroids_m = centroids_.data() + offset * k * sizeof(T);
185	
186	  // Non-spherical L2 KMeans: the PQ codebook must minimize L2 reconstruction
187	  // error, so centroids are the true (magnitude-preserving) means.
188	  ailego::NumericalKmeans<T, SingleQueueIndexThreads> algorithm(k, d);
189	
190	  // Append sub-vectors (NumericalKmeans handles transpose internally)
191	  for (size_t i = 0; i < num; ++i) {
192	    const T *sub_vec =
193	        reinterpret_cast<const T *>(reinterpret_cast<const uint8_t *>(data) +
194	                                    i * stride) +
195	        offset;
196	    algorithm.append(sub_vec, d);
197	  }
198	
199	  // Single-threaded pool -- parallelism is at the chunk level.
200	  auto local_threads = std::make_shared<SingleQueueIndexThreads>(1, false);
201	
202	  // KMC2 centroid initialization.
203	  ailego::Kmc2CentroidsGenerator<
204	      ailego::NumericalKmeans<T, SingleQueueIndexThreads>,
205	      SingleQueueIndexThreads>
206	      gen;
207	  gen.set_chain_length(markov_chain_length_);
208	  gen.set_assumption_free(false);
209	  algorithm.init_centroids(*local_threads, gen);
210	
211	  // Lloyd iterations
212	  double cost = 0.0;
213	  for (uint32_t iter = 0; iter < max_iters; ++iter) {
214	    double old_cost = cost;
215	    bool result = algorithm.cluster_once(*local_threads, &cost);
216	    if (!result) {
217	      break;
218	    }
219	    double new_epsilon = std::abs(cost - old_cost);
220	    if (new_epsilon < epsilon_) {
221	      break;
222	    }
223	  }
224	
225	  // Extract centroids into the flat centroids_ byte buffer
226	  const auto &cents = algorithm.centroids();
227	  for (size_t c = 0; c < cents.count(); ++c) {
228	    std::memcpy(centroids_m + c * d * sizeof(T), cents[c], d * sizeof(T));
229	  }
230	}
