319	void PqInt8Quantizer::train_all_chunks(const void *data, size_t num,
320	                                       size_t stride, uint32_t max_iters) {
321	  // Create thread pool.
322	  auto threads =
323	      std::make_shared<SingleQueueIndexThreads>(thread_count_, false);
324	  auto task_group = threads->make_group();
325	
326	  // Distribute chunks across threads, dispatched by data type.
327	  std::atomic<size_t> finished{0};
328	  size_t pool_count = threads->count();
329	
330	  auto submit_training = [&](const auto *typed_data) {
331	    using T = std::remove_const_t<std::remove_pointer_t<decltype(typed_data)>>;
332	    for (size_t i = 0; i < pool_count; ++i) {
333	      task_group->submit(
334	          ailego::Closure::New([this, typed_data, num, stride, i, pool_count,
335	                                max_iters, &finished]() {
336	            for (uint32_t m = static_cast<uint32_t>(i); m < num_chunk_;
337	                 m += static_cast<uint32_t>(pool_count)) {
338	              train_chunk<T>(typed_data, num, stride, m, max_iters);
339	              finished++;
340	            }
341	          }));
342	    }
343	  };
344	
345	  switch (input_data_type_) {
346	    case DataType::kFp16:
347	      submit_training(reinterpret_cast<const ailego::Float16 *>(data));
348	      break;
349	    case DataType::kFp32:
350	      submit_training(reinterpret_cast<const float *>(data));
351	      break;
352	    default:
353	      break;
354	  }
355	
356	  task_group->wait_finish();
357	}
